// ─── File: MigrationDemo.java ───
// Runnable ETL demo. Each class would be in its own file in a real project.
package com.bank.migration;

import java.math.BigDecimal;
import java.util.*;
import java.util.logging.*;

public class MigrationDemo {
    private static final Logger log = Logger.getLogger(MigrationDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        // Raw legacy rows: pipe-delimited mainframe dump staged in S3.
        // Fields: custId|name|occupation|kycCode|accId|type|balanceStr|statusCode
        List<LegacyRecord> raw = new ArrayList<>();
        raw.add(new LegacyRecord("CUST01|Rajesh Kumar|Software Engineer|V|SAV2001|S|1,000,000.00|A"));
        raw.add(new LegacyRecord("CUST02|Priya Sharma|Property Owner|V|CUR3001|C|250,000.00|A"));
        raw.add(new LegacyRecord("CUST01|Rajesh Kumar|Software Engineer|V|SAV2001|S|1,000,000.00|A")); // duplicate
        raw.add(new LegacyRecord("CUST03|Bad Row|Unknown|X|ACC9999|S|-500.00|A"));                     // invalid

        LegacyExtractor extractor = new LegacyExtractor(raw);
        RecordTransformer transformer = new RecordTransformer();
        RejectedStore rejects = new RejectedStore();
        CloudLoader loader = new CloudLoader();  // idempotent upsert simulation

        // ETL pipeline
        for (LegacyRecord rec : extractor.extract()) {
            try {
                CustomerAccount clean = transformer.transform(rec);
                loader.upsert(clean);  // safe to run twice — keyed on accountId
            } catch (ValidationException ve) {
                rejects.reject(rec.rawLine, ve.getMessage());
                log.severe("REJECTED [" + ve.getMessage() + "] : " + rec.rawLine);
            }
        }

        // Reconciliation: compare source vs target
        Reconciler reconciler = new Reconciler();
        reconciler.reconcile(raw, loader);
        log.info(() -> "Loaded accounts = " + loader.count() + ", rejected = " + rejects.count());
    }
}

// ─── model/LegacyRecord.java ───
class LegacyRecord {
    final String rawLine;
    LegacyRecord(String rawLine) { this.rawLine = rawLine; }
}

// ─── model/CustomerAccount.java ───
class CustomerAccount {
    final String customerId, fullName, occupation, kycStatus;
    final String accountId, accountType, status;
    final BigDecimal balance;
    CustomerAccount(String customerId, String fullName, String occupation, String kycStatus,
                    String accountId, String accountType, BigDecimal balance, String status) {
            this.customerId = customerId;
            this.fullName = fullName
            this.occupation = occupation;
            this.kycStatus = kycStatus;
            this.accountId = accountId
            this.accountType = accountType;
        this.balance = balance; this.status = status;
    }
}

// ─── transform/ValidationException.java ───
class ValidationException extends Exception {
    ValidationException(String msg) { super(msg); }
}

// ─── extract/LegacyExtractor.java ───
class LegacyExtractor {
    private final List<LegacyRecord> source;
    LegacyExtractor(List<LegacyRecord> source) { this.source = source; }
    List<LegacyRecord> extract() { return source; } // real impl streams from S3 staging
}

// ─── transform/RecordTransformer.java ───
// Cleans, parses, maps codes, and validates each row into the new schema.
class RecordTransformer {
    CustomerAccount transform(LegacyRecord rec) throws ValidationException {
        String[] f = rec.rawLine.split("\\|");
        if (f.length != 8) throw new ValidationException("wrong column count");
        String custId = f[0].trim();
        String name = f[1].trim();
        String occupation = f[2].trim();
        String kyc = mapKyc(f[3].trim());
        String accId = f[4].trim();
        String type = mapType(f[5].trim());
        BigDecimal balance = parseAmount(f[6].trim());
        String status = mapStatus(f[7].trim());
        if (balance.signum() < 0) throw new ValidationException("negative balance not allowed");
        if ("UNKNOWN".equals(kyc)) throw new ValidationException("unknown KYC code");
        return new CustomerAccount(custId, name, occupation, kyc, accId, type, balance, status);
    }
    private BigDecimal parseAmount(String s) throws ValidationException {
        try { return new BigDecimal(s.replace(",", "")); }
        catch (NumberFormatException e) { throw new ValidationException("bad balance format: " + s); }
    }
    private String mapKyc(String c) { return "V".equals(c) ? "VERIFIED" : "UNKNOWN"; }
    private String mapType(String c) { return "S".equals(c) ? "SAVINGS" : "C".equals(c) ? "CURRENT" : "UNKNOWN"; }
    private String mapStatus(String c) { return "A".equals(c) ? "ACTIVE" : "INACTIVE"; }
}

// ─── load/CloudLoader.java ───
// Idempotent: upsert keyed on accountId. Re-running updates, never duplicates.
class CloudLoader {
    private static final Logger log = Logger.getLogger(CloudLoader.class.getName());
    private final Map<String, CustomerAccount> db = new LinkedHashMap<>(); // simulates Aurora
    void upsert(CustomerAccount a) {
        boolean existed = db.containsKey(a.accountId);
        db.put(a.accountId, a);
        log.info((existed ? "UPDATED " : "INSERTED ") + a.accountId
                + " (" + a.fullName + ", balance=" + a.balance + ")");
    }
    int count() { return db.size(); }
    BigDecimal totalBalance() {
        return db.values().stream().map(a -> a.balance).reduce(BigDecimal.ZERO, BigDecimal::add);
    }
}

// ─── load/RejectedStore.java ───
class RejectedStore {
    private final List<String> rejects = new ArrayList<>();
    void reject(String raw, String reason) { rejects.add(reason + " :: " + raw); }
    int count() { return rejects.size(); }
}

// ─── reconcile/Reconciler.java ───
// Compares source balance total vs loaded balance total.
class Reconciler {
    private static final Logger log = Logger.getLogger(Reconciler.class.getName());
    void reconcile(List<LegacyRecord> source, CloudLoader loader) {
        // Source total: parse valid, non-negative, deduplicated balances
        Map<String, BigDecimal> uniqueSrc = new HashMap<>();
        for (LegacyRecord r : source) {
            String[] f = r.rawLine.split("\\|");
            if (f.length != 8) continue;
            try {
                BigDecimal bal = new BigDecimal(f[6].trim().replace(",", ""));
                if (bal.signum() >= 0 && "V".equals(f[3].trim())) uniqueSrc.put(f[4].trim(), bal);
            } catch (NumberFormatException ignore) { }
        }
        BigDecimal srcTotal = uniqueSrc.values().stream().reduce(BigDecimal.ZERO, BigDecimal::add);
        BigDecimal tgtTotal = loader.totalBalance();
        if (srcTotal.compareTo(tgtTotal) == 0) {
            log.info("RECONCILE OK — source total = target total = " + tgtTotal);
        } else {
            log.severe("RECONCILE MISMATCH — source=" + srcTotal + " target=" + tgtTotal);
        }
    }
}

// ─── Clean log formatter ───
class BankLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tF %1$tT [%2$-7s] %3$s%n",
                new java.util.Date(r.getMillis()), r.getLevel(), formatMessage(r));
    }
}
